    rchi = s.line(["مربع كاي", f"=(B{rc}-(B{rc}+B{rt})*B{rs})^2/((B{rc}+B{rt})*B{rs})+(B{rt}-(B{rc}+B{rt})*(1-B{rs}))^2/((B{rc}+B{rt})*(1-B{rs}))"], ["label", "formula"], [None, "0.00"])
    rp = s.line(["القيمة الاحتمالية", f"=CHIDIST(B{rchi},1)"], ["label", "formula"], [None, "0.000"])
    r = s.line(["الحكم", f'=IF(B{rp}<0.01,"إنذار: افحص التوزيع قبل قراءة النتيجة","التوزيع سليم")'], ["label", "formula"])
    s.skip()
    s.section("2) الفرق وفترة الثقة مقابل عتبة الجدوى", span=4)
    s.header(["البند", "الضابطة", "المعالجة", ""])
    rn = s.line(["عدد العملاء", 20000, 20000], ["label", "input", "input"], [None, "#,##0", "#,##0"])
    rx = s.line(["عدد من سددوا", 1000, 1120], ["label", "input", "input"], [None, "#,##0", "#,##0"])
    rr = s.line(["معدل السداد", f"=B{rx}/B{rn}", f"=C{rx}/C{rn}"], ["label", "formula", "formula"], [None, "0.00%", "0.00%"])
    rd = s.line(["الفرق (نقطة مئوية)", None, f"=C{rr}-B{rr}"], ["label", None, "formula"], [None, None, "0.00%"])
    rl = s.line(["الارتفاع النسبي", None, f"=C{rd}/B{rr}"], ["label", None, "formula"], [None, None, "0%"])
    rse = s.line(["الخطأ المعياري للفرق", None, f"=SQRT(B{rr}*(1-B{rr})/B{rn}+C{rr}*(1-C{rr})/C{rn})"], ["label", None, "formula"], [None, None, "0.000%"])
    rlo = s.line(["الحد الأدنى لفترة الثقة 95%", None, f"=C{rd}-1.96*C{rse}"], ["label", None, "formula"], [None, None, "0.00%"])
    rhi = s.line(["الحد الأعلى لفترة الثقة 95%", None, f"=C{rd}+1.96*C{rse}"], ["label", None, "formula"], [None, None, "0.00%"])
    rpv = s.line(["القيمة الاحتمالية (اتجاهان)", None, f"=2*(1-NORMSDIST(ABS(C{rd}/C{rse})))"], ["label", None, "formula"], [None, None, "0.000"])
    rth = s.line(["عتبة الجدوى (نقطة مئوية)", None, 0.001], ["label", None, "input"], [None, None, "0.00%"])
    s.line(["القرار", None, f'=IF(B{rp}<0.01,"لا تُقرأ النتيجة: عدم تطابق",IF(C{rlo}>C{rth},"اعتمد: الفترة كلها فوق العتبة",IF(C{rhi}<C{rth},"لا تعتمد: الفترة كلها تحت العتبة","غير محسوم: مدّد التجربة أو وثّق المخاطرة")))'], ["label", None, "formula"])
    s.skip()
    s.section("3) حجم العينة اللازم والمدة", span=4)
    rb = s.line(["المعدل الحالي", 0.05], ["label", "input"], [None, "0.0%"])
    rm = s.line(["أصغر أثر مجدٍ (نقطة مئوية)", 0.005], ["label", "input"], [None, "0.0%"])
    rnn = s.line(["الحجم في كل مجموعة (دلالة 5%، قدرة 80%)", f"=ROUNDUP((1.959964+0.841621)^2*(B{rb}*(1-B{rb})+(B{rb}+B{rm})*(1-B{rb}-B{rm}))/B{rm}^2,0)"], ["label", "formula"], [None, "#,##0"])
    rw = s.line(["الوحدات المتاحة أسبوعيا", 4000], ["label", "input"], [None, "#,##0"])
    s.line(["المدة اللازمة (أسابيع)", f"=ROUNDUP(2*B{rnn}/B{rw},0)"], ["label", "formula"])
    s.line(["قرارك بشأن المدة", ""], ["label", "input"])
    s.dropdown(f"B{s.row - 1}", ["ننتظر المدة كاملة", "نقبل كشف أثر أكبر", "نبحث عن معيار أكثر حساسية"])
    s.note("جرّب: اجعل عدد الضابطة في الفحص 20,600 بدل 20,150، ثم اجعل حجم المجموعتين 10,000 وعدد من سددوا 500 و560.", span=4)

    s = b.sheet("تمرين_2", (36, 14, 14, 16, 14, 22))
    s.title("فرق الفروق ولوحة المتابعة", span=6)
    s.header(["المجموعة", "قبل", "بعد", "التغير", "", ""])
    r1 = s.line(["منطقة البرنامج (ألف ريال أسبوعيا)", 100, 112, None], ["label", "input", "input", "formula"])
    s.put(r1, 4, f"=C{r1}-B{r1}", "formula")
    r2 = s.line(["منطقة المقارنة", 95, 100, None], ["label", "input", "input", "formula"])
    s.put(r2, 4, f"=C{r2}-B{r2}", "formula")
    r3 = s.line(["الأثر بفرق الفروق", None, None, f"=D{r1}-D{r2}"], ["label", None, None, "formula"])
    s.line(["مبالغة المقارنة قبل وبعد وحدها", None, None, f"=D{r1}/D{r3}-1"], ["label", None, None, "formula"], [None, None, None, "0%"])
    s.line(["هل فحصت الاتجاه المتوازي قبل البرنامج؟", ""], ["label", "input"])
    s.dropdown(f"B{s.row - 1}", ["نعم ومتوازٍ", "نعم وغير متوازٍ", "لا"])
    s.skip()
    s.section("لوحة متابعة القرار", span=6)
    s.header(["المؤشر", "المستهدف", "عتبة الإنذار", "الاتجاه المرغوب", "القيمة الحالية", "الحالة"])
    for name, tgt, thr, d, cur, fmt in [("وصول العرض إلى المستهدفين", 0.9, 0.8, "أعلى", 0.86, "0%"),
                                        ("نسبة قبول العرض", 0.20, 0.15, "أعلى", 0.12, "0%"),
                                        ("معدل الانسحاب الربعي", 0.040, 0.045, "أقل", 0.043, "0.0%"),
                                        ("متوسط الإيراد للعميل (ريال)", 45, 42, "أعلى", 41, "0"),
                                        ("الضبط للنموذج", 0.125, 0.10, "أعلى", 0.11, "0.0%")]:
        r = s.line([name, tgt, thr, d, cur, None], ["label", "text", "text", "text", "input", "formula"], [None, fmt, fmt, None, fmt, None])
        s.put(r, 6, f'=IF(E{r}="","",IF(OR(AND(D{r}="أعلى",E{r}<C{r}),AND(D{r}="أقل",E{r}>C{r})),"إنذار: راجع الشرط","على المسار"))', "formula")
    s.line(["ما الإجراء الذي يستدعيه أول إنذار؟", ""], ["label", "input"])

